SELECT 'p2/2 AFTER' AS stage, count(*) AS collocations FROM vocab_collocations;

-- ── 最后一片:总量 count-validate,四行都必须是 t,否则 ROLLBACK ──
SELECT '搭配总数 = 22070' AS expect,
       (SELECT count(*) FROM vocab_collocations) = 22070 AS ok
UNION ALL
SELECT '覆盖 4415 个词',
       (SELECT count(DISTINCT word_id) FROM vocab_collocations) = 4415
UNION ALL
SELECT '没有孤儿搭配',
       NOT EXISTS (SELECT 1 FROM vocab_collocations c LEFT JOIN vocab_words w ON w.id = c.word_id WHERE w.id IS NULL)
UNION ALL
SELECT '没有与例句搭配重复的',
       NOT EXISTS (
         SELECT 1 FROM vocab_collocations c JOIN vocab_examples e ON e.word_id = c.word_id
          WHERE lower(btrim(c.collocation)) = lower(btrim(e.collocation))
       );

COMMIT;
